style.css:
@-moz-document domain("youtube.com") {
/* =======================================================
       1. FULL BACKGROUND IMAGE & QUALITY TUNING
       ======================================================= */
    html, body, ytd-app, #content, #page-manager {
        background-image: url("https://postimg.cc") !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-position: center !important;
        background-repeat: no-repeat !important;
        image-rendering: -webkit-optimize-contrast !important;
        image-rendering: crisp-edges !important;
    }

    /* =======================================================
       2. TRANSPARENCY FIX (REMOVES WHITE BOXES)
       ======================================================= */
    ytd-browse, ytd-watch-flexy, ytd-masthead, #columns, #primary, #secondary, 
    #background.ytd-masthead, ytd-guide-renderer, #contentContainer, 
    ytd-mini-guide-renderer, #guide-wrapper, ytd-rich-item-renderer, 
    ytd-rich-grid-row, #contents.ytd-rich-grid-renderer {
        background: transparent !important;
        background-color: transparent !important;
    }

    /* =======================================================
       3. DARK BLUR MENUS FOR EASIER TEXT READING
       ======================================================= */
    ytd-rich-grid-renderer, ytd-search-box, #watch-card, #meta, #ticket-shelf, 
    #clarification-box, .ytd-watch-metadata, ytd-live-chat-frame, #sections.ytd-guide-renderer {
        background: rgba(0, 0, 0, 0.4) !important;
        backdrop-filter: blur(4px);
        border-radius: 12px;
        padding: 10px;
    }

    /* =======================================================
       4. CUSTOM LOGO / GIF ICON REPLACEMENT (SINGLE LOGO FIX)
       ======================================================= */
    /* Hides the default red YouTube vector graphics */
    #logo ytd-logo svg,
    #logo .yt-icon,
    ytd-topbar-logo-renderer svg {
        display: none !important;
    }

    /* 1. Turns off the duplicate background on the inner container */
    #logo ytd-logo {
        background: transparent !important;
    }

    /* 2. Applies your single custom GIF to the main outer container */
    ytd-topbar-logo-renderer #logo {
        background: url("https://i.postimg.cc/RZtKpZTw/b69f76df198fa55d573f2c9b616cb303-1.gif") no-repeat center left !important;
        background-size: contain !important;
        min-width: 160px !important;  /* Width for your full-body character */
        height: 56px !important;      /* Container height */
        display: block !important;
        transform: scale(1.3) !important; /* Blows up the scale */
        transform-origin: left center !important;
        margin-top: -5px !important;  /* Centers it vertically */
    }
}
